INSERT INTO `message` VALUES (1,1,'UNKNOWN_KEYWORD_ADVICE','Unknown keyword. Reply with MENU to see available services. Looking for a date? Reply with the word \'date\' and we\'ll find a match for you!'),(2,1,'MAIN_MENU_ADVICE','Reply with number to see sub-menu, 0 to go back. SMS cost 0.0/-'),(3,1,'CONFIRMED_SUBSCRIPTION_ADVICE','You\'ve been subscribed to \"<SERVICE_NAME>\". Quality content sent daily. Cost <SMS_SUBSCRIPTION_PRICE> /- @sms. To unsubscribe, reply \"STOP <KEYWORD>\". Reply 0 to go back to menu.'),(5,1,'SUBSCRIPTION_ADVICE','Reply with corresponding number to subscribe, 0 to go back.'),(6,1,'ALREADY_SUBSCRIBED_ADVICE','You\'re already subscribed to <KEYWORD>. If you want to unsubscribe, reply \"STOP <KEYWORD>\"'),(7,2,'MAIN_MENU_ADVICE','Reply with number, 0 to go back. SMS cost 0.0/-'),(8,2,'SUBSCRIPTION_ADVICE','You\'ve been subscribed to <SERVICE>. SMS Cost <PRICE>/- daily.'),(9,1,'DOUBLE_CONFIRMATION_ADVICE','Reply with \"ON <CHOSEN>\" to confirm content subscription to <SERVICE_NAME>,  0 To go back.'),(10,2,'CONFIRMED_SUBSCRIPTION_ADVICE','You\'ve been subscribed to \"<SERVICE_NAME>\". Quality content sent daily. Cost <SMS_SUBSCRIPTION_PRICE> /- @sms. To unsubscribe, reply \"STOP <KEYWORD>\". Reply 0 to go back to menu.'),(11,2,'ALREADY_SUBSCRIBED_ADVICE','You\'re already subscribed to <SERVICE_NAME>.  SMS Cost <PRICE>/- daily.'),(12,1,'NO_PENDING_SUBSCRIPTION_ADVICE','You don\'t have any pending subscriptions'),(13,1,'UNSUBSCRIBED_SINGLE_SERVICE_ADVICE','We are sad to see you go :( You\'ve been unsubscribed from <SERVICE_NAME> and you\'ll no longer receive content from the service. Are you lonesome? Reply with \'DATE\' and we\'ll find someone for you.'),(14,1,'UNSUBSCRIBED_ALL_ADVICE','You\'ve been unsubscribed from all services. Reply with MORE for more interesting content.'),(15,1,'INDIVIDUAL_UNSUBSCRIBE_ADVICE','Reply with \"STOP #\" where # is the number corresponding to the service you want to unsubscribe from.'),(16,1,'NOT_SUBSCRIBED_TO_ANY_SERVICE_ADVICE','You\'re not subscribed to any service.'),(17,1,'DATING_SUCCESS_REGISTRATION','Please answer some questions to complete your dating profile.'),(18,2,'DATING_SUCCESS_REGISTRATION','Answer only 6 questions to complete your dating profile.'),(19,1,'USERNAME_NOT_UNIQUE_TRY_AGAIN','The username  \"<USERNAME>\" you chose is not unique. Please reply with another username.'),(20,2,'USERNAME_NOT_UNIQUE_TRY_AGAIN','The username  \"<USERNAME>\" you chose is not unique. Please reply with another username.'),(21,1,'PROFILE_COMPLETE','Congratulations <USERNAME>! Your dating profile is complete. Now sit back, relax and wait for us to find a match for you near your area.'),(22,2,'PROFILE_COMPLETE','Congratulations <USERNAME>! Your dating profile is complete. Now sit back, relax and wait for us to find a match for you near your area.'),(23,1,'AGE_NUMBER_INCORRECT','Sorry <USERNAME>, we didn\'t understand age specified. Please reply with a number representing age in years. For example 23'),(24,2,'AGE_NUMBER_INCORRECT','Sorry <USERNAME>, we didn\'t understand age specified. Please reply with a number representing age in years. For example 23'),(25,1,'SERVICE_FOR_18_AND_ABOVE','Sorry <USERNAME>, this service is only for adults who are 18 years and above. The age you specified does not qualify for this service.'),(26,2,'SERVICE_FOR_18_AND_ABOVE','Sorry <USERNAME>, this service is only for adults who are 18 years and above. The age you specified does not qualify for this service.'),(35,1,'GENDER_NOT_UNDERSTOOD','Sorry, gender not understood. Please specify either MALE or FEMALE.'),(36,2,'GENDER_NOT_UNDERSTOOD','Sorry, gender not understood. Please specify either MALE or FEMALE.'),(37,1,'RENEW_SUBSCRIPTION','Sorry, Please renew your subscription to continue enjoying enjoying the service. Reply with RENEW to confirm service renewal.'),(38,2,'RENEW_SUBSCRIPTION','Sorry, Please renew your subscription to continue enjoying enjoying the service. Reply with RENEW to confirm service renewal.'),(39,1,'SUBSCRIPTION_RENEWED','Your subscription has been renewed up to <EXPIRY_DATE>. You can now continue to enjoy the <SERVICE_NAME>.'),(40,2,'SUBSCRIPTION_RENEWED','Your subscription has been renewed up to <EXPIRY_DATE>. You can now continue to enjoy the <SERVICE_NAME>.'),(41,1,'RENEW_CHAT_SUBSCRIPTION','Sorry <USERNAME>. Please top up & renew your <SERVICE_NAME> subscription to continue chatting with <DEST_USERNAME>. Reply with RENEW to confirm service renewal.'),(42,2,'RENEW_CHAT_SUBSCRIPTION','Sorry <USERNAME>. Please top up & renew your <SERVICE_NAME> subscription to continue chatting with <DEST_USERNAME>. Reply with RENEW to confirm service renewal.'),(43,1,'INSUFFICIENT_FUNDS','Sorry. You don\'t have sufficient funds. Please top up and try again.'),(44,2,'INSUFFICIENT_FUNDS','Sorry. You don\'t have sufficient funds. Please top up and try again.'),(45,1,'BILLING_FAILED','Sorry, we couldn\'t process your request at this time. Please try again after some time.'),(46,2,'BILLING_FAILED','Sorry, we couldn\'t process your request at this time. Please try again after some time.'),(47,1,'COULD_NOT_FIND_MATCH_AT_THE_MOMENT','Sorry <USERNAME>, we couldn\'t find a match near you but do keep trying. We will also update you on SMS if the system finds a match for you.'),(48,2,'COULD_NOT_FIND_MATCH_AT_THE_MOMENT','Sorry <USERNAME>, we couldn\'t find a match near you but do keep trying. We will also update you on SMS if the system finds a match for you.'),(49,1,'GENDER_PRONOUN_M','his'),(50,2,'GENDER_PRONOUN_M','his'),(51,1,'GENDER_PRONOUN_F','her'),(52,2,'GENDER_PRONOUN_F','her'),(53,1,'GENDER_PRONOUN_N','them'),(54,2,'GENDER_PRONOUN_N','them'),(55,1,'MATCH_FOUND','Lucky you <USERNAME>! We have a match for you. <PROFILE>. <GENDER_PRONOUN> username is <DEST_USERNAME>. To chat with <GENDER_PRONOUN2>, compose a message starting with the word \"<DEST_USERNAME>\"'),(56,2,'MATCH_FOUND','Lucky you <USERNAME>! We have a match for you. <PROFILE>. <GENDER_PRONOUN> username is <DEST_USERNAME>. To chat with <GENDER_PRONOUN2>, compose a message starting with the word \"<DEST_USERNAME>\"'),(57,1,'GENDER_PRONOUN_INCHAT_F','her'),(58,2,'GENDER_PRONOUN_INCHAT_F','her'),(59,1,'GENDER_PRONOUN_INCHAT_M','him'),(60,2,'GENDER_PRONOUN_INCHAT_M','him'),(62,1,'MUST_AGREE_TO_TNC','You must agree/disagree to T&C b4 proceeding.'),(63,2,'MUST_AGREE_TO_TNC','You must agree/disagree to T&C b4 proceeding.');
